from solution import move_one_ball
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference_brute_force(arr):
    """Obviously-correct model: some number of right shifts yields sorted order."""
    if len(arr) == 0:
        return True
    s = sorted(arr)
    n = len(arr)
    for k in range(n):
        if k == 0:
            rot = list(arr)
        else:
            rot = list(arr[n - k:]) + list(arr[:n - k])
        if rot == s:
            return True
    return False


def count_wraps(arr):
    """Number of indices i with arr[i] > arr[(i+1) % n]."""
    n = len(arr)
    if n == 0:
        return 0
    c = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            c += 1
    return c


def test_empty_returns_true():
    assert move_one_ball([]) is True


def test_spec_example_true():
    assert move_one_ball([3, 4, 5, 1, 2]) is True


def test_spec_example_false():
    assert move_one_ball([3, 5, 4, 1, 2]) is False


def test_result_is_bool():
    assert move_one_ball([]) is True
    assert move_one_ball([3, 4, 5, 1, 2]) in (True, False)
    assert type(move_one_ball([3, 4, 5, 1, 2])) is bool
    assert type(move_one_ball([3, 5, 4, 1, 2])) is bool


def test_two_sorted_examples_are_bool_exact():
    assert move_one_ball([3, 4, 5, 1, 2]) is True
    assert move_one_ball([3, 5, 4, 1, 2]) is False


@given(st.integers(min_value=-100, max_value=100))
def test_single_element_always_true(x):
    assert move_one_ball([x]) is True


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=0, max_size=8))
def test_sorted_unique_always_true(arr):
    s = sorted(arr)
    assert move_one_ball(s) is True
    assert move_one_ball(list(s)) is True


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=0, max_size=8))
def test_length_less_than_3_always_true(arr):
    assume(len(arr) < 3)
    assert move_one_ball(list(arr)) is True


@given(
    st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=3, max_size=8),
    st.integers(min_value=0, max_value=20),
)
def test_right_shift_of_sorted_always_true(arr, k):
    s = sorted(arr)
    n = len(s)
    kk = k % n
    if kk == 0:
        rot = list(s)
    else:
        rot = s[n - kk:] + s[:n - kk]
    assert move_one_ball(rot) is True


@given(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=3, max_size=8))
def test_reverse_sorted_long_is_false(arr):
    s = sorted(arr)
    assume(len(s) >= 3)
    rev = s[::-1]
    # reverse of strictly sorted unique list of length >= 3 cannot be a rotation of sorted
    assert move_one_ball(rev) is False
    assert reference_brute_force(rev) is False


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=0, max_size=8))
def test_equivalence_to_brute_force_reference(arr):
    assert move_one_ball(list(arr)) is reference_brute_force(list(arr))


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=0, max_size=8))
def test_equivalence_to_wrap_break_model(arr):
    # For unique elements: rotatable-sortable iff at most one wrap break.
    expected = count_wraps(list(arr)) <= 1
    assert move_one_ball(list(arr)) is expected


@given(
    st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=1, max_size=8),
    st.integers(min_value=0, max_value=20),
)
def test_rotation_invariance(arr, k):
    n = len(arr)
    kk = k % n
    if kk == 0:
        rot = list(arr)
    else:
        rot = arr[n - kk:] + arr[:n - kk]
    assert move_one_ball(rot) == move_one_ball(list(arr))


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=1, max_size=8))
def test_true_implies_rotation_starting_at_min_is_sorted(arr):
    res = move_one_ball(list(arr))
    if res is True:
        m = min(arr)
        idx = arr.index(m)
        rot = arr[idx:] + arr[:idx]
        assert rot == sorted(arr)
    else:
        # False implies no rotation is sorted
        assert reference_brute_force(list(arr)) is False


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=1, max_size=8))
def test_true_implies_sorted_is_reachable_by_right_shifts(arr):
    assume(move_one_ball(list(arr)) is True)
    s = sorted(arr)
    n = len(arr)
    found = any(
        (list(arr) if k == 0 else list(arr[n - k:]) + list(arr[:n - k])) == s
        for k in range(n)
    )
    assert found is True


@given(st.lists(st.integers(min_value=-50, max_value=50), unique=True, min_size=1, max_size=8))
def test_false_implies_no_right_shift_sorts(arr):
    assume(move_one_ball(list(arr)) is False)
    s = sorted(arr)
    n = len(arr)
    for k in range(n):
        if k == 0:
            rot = list(arr)
        else:
            rot = list(arr[n - k:]) + list(arr[:n - k])
        assert rot != s


def test_already_sorted_needs_zero_shifts():
    assert move_one_ball([1, 2, 3, 4]) is True
    assert move_one_ball([1]) is True
    assert move_one_ball([]) is True


def test_two_elements_both_orders_true():
    assert move_one_ball([1, 2]) is True
    assert move_one_ball([2, 1]) is True


def test_single_drop_true():
    assert move_one_ball([2, 3, 4, 5, 1]) is True
    assert move_one_ball([5, 1, 2, 3, 4]) is True
    assert move_one_ball([1, 2, 3, 4, 5]) is True


def test_two_drops_false():
    assert move_one_ball([1, 3, 2, 4]) is False
    assert move_one_ball([3, 5, 4, 1, 2]) is False
    assert move_one_ball([4, 3, 2, 1]) is False
